package io.knowledgebrain.learning;
import java.util.*;import java.time.*;import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import org.springframework.web.client.RestClient;import org.springframework.test.web.client.MockRestServiceServer;import static org.springframework.test.web.client.response.MockRestResponseCreators.*;import org.springframework.http.MediaType;import org.springframework.web.server.ResponseStatusException;
class CourseContextClientTest {
 UUID actor,group,space,course,enrollment,study;CourseContextClient client;MockRestServiceServer server;String token="a".repeat(43),trace="00-"+"b".repeat(32)+"-"+"c".repeat(16)+"-01";
 @BeforeEach void setup(){var ids=new UuidV7(Clock.systemUTC());actor=ids.next();group=ids.next();space=ids.next();course=ids.next();enrollment=ids.next();study=ids.next();var builder=RestClient.builder().baseUrl("https://collaboration.invalid");server=MockRestServiceServer.bindTo(builder).build();client=new CourseContextClient(builder.build());}
 String response(){return "{\"principalId\":\""+actor+"\",\"groupId\":\""+group+"\",\"spaceId\":\""+space+"\",\"courseId\":\""+course+"\",\"courseVersion\":3,\"courseState\":\"ACTIVE\",\"role\":\"MEMBER\",\"enrollmentId\":\""+enrollment+"\",\"enrollmentVersion\":1,\"enrollmentState\":\"ENROLLED\",\"studies\":[{\"studyId\":\""+study+"\",\"studyVersion\":1,\"title\":\"Study\"}]}";}
 @Test void fixedTlsReferenceDelegatesOnlyOneBrowserTokenAndTrace(){server.expect(r->{assertEquals("/api/groups/"+group+"/courses/"+course+"/learning-context",r.getURI().getPath());assertEquals("__Host-brain_guest="+token,r.getHeaders().getFirst("Cookie"));assertEquals(trace,r.getHeaders().getFirst("traceparent"));assertNull(r.getHeaders().getFirst("Authorization"));assertNull(r.getHeaders().getFirst("Origin"));}).andRespond(withSuccess(response(),MediaType.APPLICATION_JSON));assertTrue(client.check(group,course,token,trace).writable());server.verify();}
 @Test void malformedForeignAndAmbiguousContextFailsClosed(){for(String body:List.of(response()+" {}",response().replace(group.toString(),space.toString()),response().replace("\"courseVersion\":3","\"courseVersion\":3.5"),response().replace("\"role\":\"MEMBER\"","\"role\":\"ROOT\""),response().replace("\"title\":\"Study\"","\"title\":\"\""),response().replace("\"enrollmentId\":\""+enrollment+"\"","\"enrollmentId\":null")," ".repeat(65537))){server.reset();server.expect(r->{}).andRespond(withSuccess(body,MediaType.APPLICATION_JSON));assertEquals(503,assertThrows(ResponseStatusException.class,()->client.check(group,course,token,trace)).getStatusCode().value());server.verify();}}
 @Test void upstreamDenialAndFailureAreNotCached(){server.expect(r->{}).andRespond(withStatus(org.springframework.http.HttpStatus.NOT_FOUND));assertEquals(404,assertThrows(ResponseStatusException.class,()->client.check(group,course,token,trace)).getStatusCode().value());server.reset();server.expect(r->{}).andRespond(withServerError());assertEquals(503,assertThrows(ResponseStatusException.class,()->client.check(group,course,token,trace)).getStatusCode().value());server.verify();}
}
